mapper.select:
SELECT id, order_no, platform_order_no, room_id, channel_id, creator_id, member_id,
       guest_name, phone, guest_count, check_in, check_out, status, remark
FROM orders WHERE id = #{id}

SELECT id, order_no, platform_order_no, room_id, channel_id, creator_id, member_id,
       guest_name, phone, guest_count, check_in, check_out, status, remark
FROM orders WHERE id = #{id} AND member_id = #{memberId}

SELECT 
FROM orders o
INNER JOIN room r ON r.id = o.room_id
INNER JOIN channels c ON c.id = o.channel_id
INNER JOIN order_amount a ON a.order_id = o.id
WHERE o.member_id = #{memberId}
AND o.status = #{status}
ORDER BY o.created_at DESC, o.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM orders o
WHERE o.member_id = #{memberId}
AND o.status = #{status}

