INSERT INTO orders (
    order_no, platform_order_no, room_id, channel_id, creator_id, member_id,
    guest_name, phone, guest_count, check_in, check_out, status, remark
) VALUES (
    #{orderNo}, #{platformOrderNo}, #{roomId}, #{channelId}, #{creatorId}, #{memberId},
    #{guestName}, #{phone}, #{guestCount}, #{checkIn}, #{checkOut}, #{status}, #{remark}
)

mapper.update:
UPDATE orders
SET room_id = #{roomId}, guest_name = #{guestName}, phone = #{phone}, guest_count = #{guestCount},
    check_in = #{checkIn}, check_out = #{checkOut}, remark = #{remark}
WHERE id = #{id}

